 await setup();await page.locator('#remote-browser-enable').check();assert.equal(await page.locator('#remote-password-form').isVisible(),false,'provider removal preserves independent password');await save();await page.locator('#remote-access-state').filter({hasText:'Online'}).waitFor();await page.locator('#remote-signin').click();await page.locator('#remote-signin-link').waitFor({state:'visible'});assert.equal(await page.locator('#remote-signin-link').getAttribute('href'),'https://login.tailscale.com/a/SYNTHETIC_OWNER_SIGNIN');await close();assert.equal(await page.locator('#remote-signin-link').getAttribute('href'),null);await clean();
 await open();await setup();await page.locator('#remote-password-open').click();await page.locator('#remote-new-password').fill(password);await close();await clean();assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
 const failure=await context.newPage();await failure.route('**/api/interface',route=>route.abort());await failure.goto(new URL('/#bootstrap=SYNTHETIC_DELAYED_BOOTSTRAP',fixture.native_url).href);await failure.waitForFunction(()=>location.hash==='');assert.equal(await failure.evaluate(()=>history.state),null);await failure.close();assert.deepEqual(errors,[]);
